#pragma once

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <string>
#include <optional>
#include <unordered_map>
#include <vector>
#include <cmath>

namespace ptv {

struct ParsedControlInput {
    // Dynamic, per-frame inputs driven by the binding params_json.
    bool left_trigger{false};
    bool right_trigger{false};
    bool left_grip{false};

    // Selection from construct core: which control is currently armed.
    // Expected: "chain_tether" or "restraining_bands".
    std::string active_control{"chain_tether"};

    // Optional refined target id (string registered in world).
    std::string refined_target_id{};

    // Config params (fall back to defaults when not provided).
    float tether_max_length_m{18.0f};
    float tether_tension_break_threshold{1.0f}; // normalized
    float reel_in_speed_mps{2.0f};
    float bands_slow_per_stack{0.18f};
    int   bands_max_stacks{3};
    float fear_zone_resistance_multiplier{1.5f};
};

struct BandsRuntime {
    int stacks{0};
    float time_since_last_apply_s{0.0f};
};

struct TetherRuntime {
    bool active{false};
    std::uint32_t target_entity{0};
    ptv::Vec3 anchor_ws{0.0f,0.0f,0.0f}; // player hand/world point at latch
    float tension_norm{0.0f};
};

// Access helpers
ParsedControlInput parse_control_binding_params(World& w, std::uint32_t binding_entity, const std::string& self_mechanic_id);

// Utility: safe get entity by string id (returns entt::null as 0 if not found)
std::uint32_t find_entity(World& w, const std::string& id_str);

// Utility: push a tag string into CTag.tags if not already present
void ensure_tag(World& w, std::uint32_t e, const std::string& tag);
// Utility: remove any tag that starts with prefix
void remove_tag_prefix(World& w, std::uint32_t e, const std::string& prefix);
// Utility: check if an entity has a plain tag equal to key OR any tag that starts with key+
bool has_tag_or_prefix(World& w, std::uint32_t e, const std::string& key);

// Haptics publish helper (uses dependency contract)
void publish_haptics(World& w, std::uint32_t e, const std::string& pattern_id,
                     const std::string& hand, float intensity_scale, float duration_s);

// VFX publish helper (generic tag-based)
void spawn_vfx_line(World& w, std::uint32_t e_context,
                    const ptv::Vec3& from, const ptv::Vec3& to,
                    const std::string& asset_id,
                    float ttl_s);

// Cage tighten hint
void request_cage_tighten(World& w, std::uint32_t target,
                          float delta_radius_m, float duration_add_s, float drain_mul);

// Yellow zone detection on target (via tags)
bool is_in_yellow_zone(World& w, std::uint32_t target);

// Chain/Tether core step. Returns whether tether remains active.
bool step_tether(World& w, std::uint32_t player_hand_entity, float dt,
                 const ParsedControlInput& in,
                 TetherRuntime& tr);

// Restraining bands application and decay
void apply_bands_now(World& w, std::uint32_t target, const ParsedControlInput& in,
                     BandsRuntime& br);
void decay_bands(World& w, std::uint32_t target, float dt,
                 const ParsedControlInput& in, BandsRuntime& br);

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include "control_constructs_shared.h"
#include <algorithm>
#include <string>

namespace ptv {

std::uint32_t find_entity(World& w, const std::string& id_str) {
    auto e = w.find(id_str);
    // World::find returns entt::null for not found; ABI passes as std::uint32_t
    return e;
}

void ensure_tag(World& w, std::uint32_t e, const std::string& tag) {
    if (!w.valid(e)) return;
    CTag tagc{};
    if (w.has<CTag>(e)) {
        tagc = w.get<CTag>(e);
    }
    auto it = std::find(tagc.tags.begin(), tagc.tags.end(), tag);
    if (it == tagc.tags.end()) tagc.tags.push_back(tag);
    w.emplace_or_replace<CTag>(e, std::move(tagc));
}

void remove_tag_prefix(World& w, std::uint32_t e, const std::string& prefix) {
    if (!w.has<CTag>(e)) return;
    auto tagc = w.get<CTag>(e);
    std::vector<std::string> kept;
    kept.reserve(tagc.tags.size());
    for (auto& s : tagc.tags) {
        if (s.rfind(prefix, 0) != 0) kept.push_back(std::move(s));
    }
    tagc.tags = std::move(kept);
    w.emplace_or_replace<CTag>(e, std::move(tagc));
}

bool has_tag_or_prefix(World& w, std::uint32_t e, const std::string& key) {
    if (!w.has<CTag>(e)) return false;
    auto& tagc = w.get<CTag>(e);
    for (auto& s : tagc.tags) {
        if (s == key) return true;
        if (s.rfind(key + ":", 0) == 0) return true;
    }
    return false;
}

void publish_haptics(World& w, std::uint32_t e, const std::string& pattern_id,
                     const std::string& hand, float intensity_scale, float duration_s) {
    // Dependency contract from haptics_manager exports
    nlohmann::json j;
    j["pattern_id"] = pattern_id;
    j["hand"] = hand;
    j["intensity_scale"] = intensity_scale;
    j["duration_s"] = duration_s;
    ensure_tag(w, e, std::string("haptics.publish:") + j.dump());
}

void spawn_vfx_line(World& w, std::uint32_t e_context,
                    const ptv::Vec3& from, const ptv::Vec3& to,
                    const std::string& asset_id,
                    float ttl_s) {
    nlohmann::json j;
    j["asset"] = asset_id;               // e.g., construct_chain_tether
    j["kind"] = "line";                  // a generic line beam
    j["from"] = {from.x, from.y, from.z};
    j["to"] = {to.x, to.y, to.z};
    j["ttl_s"] = ttl_s;
    ensure_tag(w, e_context, std::string("vfx.spawn:") + j.dump());
}

void request_cage_tighten(World& w, std::uint32_t target,
                          float delta_radius_m, float duration_add_s, float drain_mul) {
    if (!w.valid(target)) return;
    nlohmann::json j;
    j["delta_radius_m"] = delta_radius_m;
    j["duration_add_s"] = duration_add_s;
    j["drain_mul"] = drain_mul;
    ensure_tag(w, target, std::string("construct.cage:tighten:") + j.dump());
}

bool is_in_yellow_zone(World& w, std::uint32_t target) {
    if (!w.has<CTag>(target)) return false;
    auto& tagc = w.get<CTag>(target);
    for (auto& s : tagc.tags) {
        if (s == "yellow_zone" || s == "yellow_zone_warning") return true;
        if (s.rfind("zone:", 0) == 0 && s.find("yellow") != std::string::npos) return true;
    }
    return false;
}

static ptv::Vec3 get_position(World& w, std::uint32_t e) {
    if (w.has<CTransform>(e)) return w.get<CTransform>(e).t.position;
    return {0.0f,0.0f,0.0f};
}

static void set_position(World& w, std::uint32_t e, const ptv::Vec3& p) {
    if (!w.has<CTransform>(e)) return;
    auto comp = w.get<CTransform>(e);
    comp.t.position = p;
    w.emplace_or_replace<CTransform>(e, comp);
}

ParsedControlInput parse_control_binding_params(World& w, std::uint32_t binding_entity, const std::string& self_mechanic_id) {
    ParsedControlInput out;
    if (!w.has<CMechanicBinding>(binding_entity)) return out;
    auto& mb = w.get<CMechanicBinding>(binding_entity);
    for (auto& e : mb.entries) {
        if (e.id == self_mechanic_id) {
            auto j = nlohmann::json::parse(e.params_json, nullptr, false);
            if (!j.is_object()) break;
            out.left_trigger = j.value("left_trigger_held", false);
            out.right_trigger = j.value("right_trigger_held", false);
            out.left_grip = j.value("left_grip_held", false);
            out.active_control = j.value("active_control", out.active_control);
            out.refined_target_id = j.value("current_target_id", std::string());
            out.tether_max_length_m = j.value("tether_max_length_m", out.tether_max_length_m);
            out.tether_tension_break_threshold = j.value("tether_tension_break_threshold", out.tether_tension_break_threshold);
            out.reel_in_speed_mps = j.value("reel_in_speed_mps", out.reel_in_speed_mps);
            out.bands_slow_per_stack = j.value("bands_slow_per_stack", out.bands_slow_per_stack);
            out.bands_max_stacks = j.value("bands_max_stacks", out.bands_max_stacks);
            out.fear_zone_resistance_multiplier = j.value("fear_zone_resistance_multiplier", out.fear_zone_resistance_multiplier);
            break;
        }
    }
    return out;
}

bool step_tether(World& w, std::uint32_t hand_e, float dt,
                 const ParsedControlInput& in,
                 TetherRuntime& tr) {
    if (!tr.active) return false;
    if (!w.valid(tr.target_entity)) { tr.active = false; return false; }

    // Comfort: visualize line each frame
    const auto hand_p = get_position(w, hand_e);
    const auto target_p = get_position(w, tr.target_entity);
    spawn_vfx_line(w, hand_e, hand_p, target_p, "construct_chain_tether", 0.05f);

    // Compute distance and tension
    ptv::Vec3 diff{target_p.x - hand_p.x, target_p.y - hand_p.y, target_p.z - hand_p.z};
    float dist = std::sqrt(diff.x*diff.x + diff.y*diff.y + diff.z*diff.z);
    float stretch = std::max(0.0f, dist - in.tether_max_length_m);

    // Simple relative-velocity proxy: how fast closing/opening this frame (comfort-safe)
    float rel_speed = 0.0f; // unavailable without velocity comps; keep 0 for stability

    tr.tension_norm = std::clamp((stretch / std::max(0.001f, in.tether_max_length_m)) + 0.25f*rel_speed*0.0f, 0.0f, 4.0f);
    float break_thresh = in.tether_tension_break_threshold;
    if (is_in_yellow_zone(w, tr.target_entity)) break_thresh /= std::max(0.01f, in.fear_zone_resistance_multiplier);

    // Reel/anchor mode on Left Trigger: gently pull target toward hand
    if (in.left_trigger) {
        if (dist > 0.001f) {
            float step = in.reel_in_speed_mps * dt;
            float t = std::min(step / dist, 0.25f); // clamp to avoid yanks
            ptv::Vec3 new_p{ target_p.x + (hand_p.x - target_p.x)*t,
                             target_p.y + (hand_p.y - target_p.y)*t,
                             target_p.z + (hand_p.z - target_p.z)*t };
            set_position(w, tr.target_entity, new_p);
        }
    }

    // Break check
    if (tr.tension_norm > break_thresh) {
        // Snap VFX + haptics
        spawn_vfx_line(w, hand_e, hand_p, target_p, "construct_chain_tether", 0.15f);
        publish_haptics(w, hand_e, "bolt_fire_sharp", "right", 0.8f, 0.08f);
        remove_tag_prefix(w, tr.target_entity, "status.tethered");
        tr.active = false;
        return false;
    }

    // Optional: if target already inside an energy cage and player is pressing LT, tighten slightly
    if (in.left_trigger && has_tag_or_prefix(w, tr.target_entity, "construct.cage:active")) {
        request_cage_tighten(w, tr.target_entity, -0.1f, 1.0f, 1.05f);
    }

    return true;
}

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include "control_constructs_shared.h"
#include <algorithm>
#include <string>

namespace ptv {

static void write_bands_tag(World& w, std::uint32_t target, int stacks, float slow_per_stack) {
    nlohmann::json j;
    j["stacks"] = stacks;
    j["slow_per_stack"] = slow_per_stack;
    ensure_tag(w, target, std::string("status.slow_bands:") + j.dump());
}

void apply_bands_now(World& w, std::uint32_t target, const ParsedControlInput& in,
                     BandsRuntime& br) {
    if (!w.valid(target)) return;
    if (br.stacks < in.bands_max_stacks) br.stacks += 1;
    br.time_since_last_apply_s = 0.0f;
    write_bands_tag(w, target, br.stacks, in.bands_slow_per_stack);
}

void decay_bands(World& w, std::uint32_t target, float dt,
                 const ParsedControlInput& in, BandsRuntime& br) {
    if (!w.valid(target)) return;
    br.time_since_last_apply_s += dt;
    // Decay after 2.0s of no refresh: drop one stack per second
    if (br.time_since_last_apply_s > 2.0f && br.stacks > 0) {
        float excess = br.time_since_last_apply_s - 2.0f;
        int drop = static_cast<int>(excess);
        if (drop > 0) {
            br.stacks = std::max(0, br.stacks - drop);
            // keep timer but clamp to fractional remainder to avoid large jumps
            br.time_since_last_apply_s = 2.0f + (excess - drop);
            if (br.stacks == 0) {
                remove_tag_prefix(w, target, "status.slow_bands");
            } else {
                write_bands_tag(w, target, br.stacks, in.bands_slow_per_stack);
            }
        }
    }
}

} // namespace ptv

#include "ptv/ecs/World.h"
#include "control_constructs_shared.h"
#include <string>

namespace ptv {

// Best-effort registration shim: advertise our control entries to the construct core
// via tag-based message the core can pick up in its own update.
static void advertise_controls(World& w, std::uint32_t hand_e) {
    nlohmann::json j1; j1["id"] = "chain_tether"; j1["asset"] = "construct_chain_tether"; j1["category"] = "Control";
    ensure_tag(w, hand_e, std::string("construct_core.register_control:") + j1.dump());
    nlohmann::json j2; j2["id"] = "restraining_bands"; j2["asset"] = "construct_chain_tether"; j2["category"] = "Control";
    ensure_tag(w, hand_e, std::string("construct_core.register_control:") + j2.dump());
}

// Exposed helper so main mechanic can call once on attach
void construct_core_advertise_if_needed(World& w, std::uint32_t hand_e) {
    advertise_controls(w, hand_e);
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>
#include <unordered_map>
#include <optional>

#include "control_constructs_shared.h"

namespace ptv {

// Forward from integration shim
void construct_core_advertise_if_needed(World& w, std::uint32_t hand_e);

class ControlConstructsExtension : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t entity, const nlohmann::json& params) override {
        (void)params;
        self_entity_ = entity;
        // Advertise our entries to construct core once
        construct_core_advertise_if_needed(w, entity);
        // Defaults are taken from parse each frame; nothing else to cache.
    }

    void on_update(World& w, std::uint32_t entity, float dt) override {
        // Parse per-frame inputs and config derived from our binding entry
        auto in = parse_control_binding_params(w, entity, id());

        // Resolve refined/current target if any
        std::uint32_t target = 0;
        if (!in.refined_target_id.empty()) target = find_entity(w, in.refined_target_id);

        // Selection routing
        if (in.active_control == "chain_tether") {
            update_tether(w, entity, target, in, dt);
        } else if (in.active_control == "restraining_bands") {
            update_bands(w, entity, target, in, dt);
        }
    }

    void on_detach(World& w, std::uint32_t entity) override {
        (void)w; (void)entity;
        tether_.active = false;
        band_targets_.clear();
    }

    std::string id() const override { return "generated.control_constructs_extension"; }

private:
    void update_tether(World& w, std::uint32_t hand_e, std::uint32_t target,
                       const ParsedControlInput& in, float dt) {
        // Fire to latch if RT pressed and we have a target and no active tether
        if (in.right_trigger && !tether_.active && w.valid(target)) {
            tether_.active = true;
            tether_.target_entity = target;
            tether_.anchor_ws = (w.has<CTransform>(hand_e) ? w.get<CTransform>(hand_e).t.position : Vec3{0,0,0});
            tether_.tension_norm = 0.0f;
            // Mark target with a transient tethered tag (consumed by other systems if any)
            nlohmann::json j; j["by"] = "ring"; j["from_entity"] = hand_e; j["max_len_m"] = in.tether_max_length_m;
            ensure_tag(w, target, std::string("status.tethered:") + j.dump());
            publish_haptics(w, hand_e, "construct_form_heavy", "right", 0.7f, 0.12f);
        }

        // Step simulation if active
        if (tether_.active) {
            if (!step_tether(w, hand_e, dt, in, tether_)) {
                // broke this frame
                tether_.active = false;
            }
        }

        // If no target or we switched selection, ensure cleanup when inactive
        if (!tether_.active && w.valid(target)) {
            remove_tag_prefix(w, target, "status.tethered");
        }
    }

    void update_bands(World& w, std::uint32_t hand_e, std::uint32_t target,
                      const ParsedControlInput& in, float dt) {
        // Apply on activation
        if (in.right_trigger && w.valid(target)) {
            auto& br = band_targets_[target];
            apply_bands_now(w, target, in, br);
            publish_haptics(w, hand_e, "bolt_fire_sharp", "right", 0.6f, 0.06f);
        }
        // Decay all tracked band targets
        std::vector<std::uint32_t> to_erase;
        for (auto& kv : band_targets_) {
            auto te = kv.first; auto& br = kv.second;
            if (!w.valid(te)) { to_erase.push_back(te); continue; }
            decay_bands(w, te, dt, in, br);
            if (br.stacks == 0) to_erase.push_back(te);
        }
        for (auto e : to_erase) band_targets_.erase(e);
    }

private:
    std::uint32_t self_entity_{0};
    TetherRuntime tether_{};
    std::unordered_map<std::uint32_t, BandsRuntime> band_targets_{};
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.control_constructs_extension", ptv::ControlConstructsExtension)
